css:
/* X09–X14. Every rule is scoped to its own scene. */
#s09 .sentence{position:absolute;left:190px;top:414px;width:1540px;display:flex;align-items:baseline;justify-content:center;gap:42px;white-space:nowrap}
#s09 .phrase{display:flex;align-items:baseline;font-size:70px;font-weight:500;letter-spacing:-2px}
#s09 .join{color:#96969d}
#s09 .word{position:relative;display:inline-block;font-size:102px;font-weight:750;letter-spacing:-3px;transform-origin:50% 75%;padding:0 10px}
#s09 .beat{position:absolute;left:4px;right:4px;bottom:-20px;height:11px;border-radius:6px;background:#cdb7f5;transform:scaleX(0);transform-origin:0 50%}
#s09 .sentence-rule{position:absolute;left:230px;right:230px;top:634px;height:2px;background:#e4e3e7}
#s09 .meaning{position:absolute;left:200px;right:200px;top:710px;text-align:center;font-size:39px;color:#73717b}
#s09 .meaning strong{color:#101112;font-weight:600}
#s09 .lead-label{position:absolute;left:230px;top:322px;font-size:28px;color:#9b97a4;letter-spacing:3px}

#s10 .question-stage{position:absolute;left:170px;top:280px;width:1580px;height:560px}
#s10 .question-rail{position:absolute;left:98px;top:36px;width:3px;height:484px;background:#e5e1eb}
#s10 .question-dot{position:absolute;left:86px;top:258px;width:27px;height:27px;background:#7451b8;border:6px solid #eee6fa;border-radius:50%;box-shadow:0 0 0 1px #cdb7f5}
#s10 .qrow{position:absolute;left:185px;top:220px;display:flex;align-items:center;gap:38px;width:1230px;height:120px;white-space:nowrap;transform-origin:0 50%}
#s10 .qnum{font-size:34px;color:#a8a3af;letter-spacing:2px;font-weight:500;width:64px;flex:none}
#s10 .qtext{font-size:96px;font-weight:700;letter-spacing:-2px}
#s10 .q2,#s10 .q3{opacity:0}
#s10 .q3 .qtext{font-size:91px}
#s10 .q3 .qtext strong{font-weight:750;color:#7451b8}
#s10 .known{position:absolute;left:1410px;top:38px;border:2px solid #dedbe4;border-radius:30px;padding:10px 24px;font-size:25px;color:#84808d;opacity:0}
#s10 .q-underline{position:absolute;left:286px;top:341px;width:910px;height:10px;border-radius:7px;background:#cdb7f5;transform-origin:left;transform:scaleX(0)}
#s10 .depth-mark{position:absolute;right:10px;bottom:30px;font-size:26px;color:#aba7b3;letter-spacing:2px;opacity:0}

#s11 .cause-map{position:absolute;inset:0;width:1920px;height:1080px;pointer-events:none}
#s11 .cause-base{stroke:#e1dce8;stroke-width:7;fill:none;stroke-linecap:round}
#s11 .cause-passed{stroke:#b497df;stroke-width:7;fill:none;stroke-linecap:round;stroke-dasharray:1180;stroke-dashoffset:1180}
#s11 .cause-tick{fill:white;stroke:#d7cedf;stroke-width:5}
#s11 .cause-signal{fill:#7451b8;stroke:#fff;stroke-width:6;opacity:0}
#s11 .cause-label{position:absolute;top:332px;width:450px;text-align:center;color:#adabb2}
#s11 .n1{left:145px}#s11 .n2{left:735px}#s11 .n3{left:1325px}
#s11 .cause-label .small{font-size:45px;font-weight:550;margin-bottom:14px}
#s11 .cause-label .large{position:relative;display:inline-block;font-size:85px;line-height:1.4;letter-spacing:-2px;font-weight:750;z-index:1}
#s11 .cause-label .outcome-bg{position:absolute;inset:0 -25px;z-index:-1;border-radius:24px;background:#101112;transform:scaleX(0);transform-origin:left}
#s11 .cause-note{position:absolute;top:674px;width:450px;text-align:center;font-size:32px;letter-spacing:1px;color:#88818f;opacity:0}
#s11 .note1{left:145px}#s11 .note2{left:735px}#s11 .note3{left:1325px}
#s11 .cause-arrow{position:absolute;top:548px;color:#b2a6c3;font-size:39px}
#s11 .arrow1{left:640px}#s11 .arrow2{left:1230px}

#s12 .correction-stage{position:absolute;left:180px;top:300px;width:1560px;height:520px}
#s12 .belief-label{position:absolute;left:40px;top:10px;color:#99949f;font-size:29px;letter-spacing:2px}
#s12 .myth{position:absolute;left:0;right:0;top:143px;display:flex;align-items:center;justify-content:center;gap:66px;font-size:81px;font-weight:650;white-space:nowrap}
#s12 .relation{position:relative;font-size:108px;width:150px;text-align:center;font-weight:400;color:#96919e}
#s12 .wrong-line{position:absolute;left:-8px;top:74px;width:0;height:10px;background:#7451b8;transform:rotate(-29deg);transform-origin:0 50%;border-radius:7px}
#s12 .myth-question{font-size:91px;color:#7451b8;margin-left:-36px}
#s12 .not-always{position:absolute;left:620px;top:27px;padding:12px 38px;border-radius:18px;background:#101112;color:#cdb7f5;font-size:47px;font-weight:700;opacity:0;transform:translateY(18px)}
#s12 .new-rule{position:absolute;left:0;right:0;top:144px;text-align:center;font-size:104px;font-weight:750;letter-spacing:-3px;opacity:0;white-space:nowrap}
#s12 .new-rule strong{position:relative;font-weight:750;color:#7451b8;z-index:1}
#s12 .goal-mark{position:absolute;left:0;right:0;bottom:0;height:27px;background:#e9ddf9;z-index:-1;transform:scaleX(0);transform-origin:left}
#s12 .action-note{position:absolute;left:0;right:0;top:364px;text-align:center;font-size:36px;line-height:1.6;color:#85818b;opacity:0}
#s12 .clear-label{position:absolute;left:40px;top:10px;color:#7451b8;font-size:29px;letter-spacing:2px;opacity:0}

#s13 .sentence-label{position:absolute;left:160px;top:280px;font-size:28px;letter-spacing:2px;color:#9a95a1}
#s13 .fragment{position:absolute;top:354px;width:480px;text-align:center;font-size:65px;line-height:1.3;white-space:nowrap;font-weight:700;letter-spacing:-2px;z-index:3;transform-origin:center center}
#s13 .f1{left:160px}#s13 .f2{left:720px}#s13 .f3{left:1280px;font-size:61px}
#s13 .punctuation{position:absolute;top:364px;font-size:62px;color:#aeabb3}
#s13 .p1{left:650px}#s13 .p2{left:1210px}#s13 .p3{left:1748px}
#s13 .step-slot{position:absolute;top:522px;width:480px;height:260px;border:2px solid #e4dfeb;border-radius:27px;background:#fff;overflow:hidden}
#s13 .slot1{left:160px}#s13 .slot2{left:720px}#s13 .slot3{left:1280px}
#s13 .slot-num{position:absolute;left:32px;top:28px;font-size:35px;font-weight:650;color:#aba2b9}
#s13 .slot-rule{position:absolute;left:31px;right:31px;top:101px;height:2px;background:#ece7f0}
#s13 .slot-fill{position:absolute;inset:0;background:#f4eefb;transform:scaleY(0);transform-origin:50% 100%}
#s13 .slot-num,#s13 .slot-rule{z-index:1}
#s13 .slot-check{position:absolute;right:34px;top:28px;color:#7451b8;font-size:31px;opacity:0}
#s13 .sequence-link{position:absolute;top:646px;font-size:42px;color:#c1b5d0;opacity:0}
#s13 .link1{left:666px}#s13 .link2{left:1226px}
#s13 .sentence-guide{position:absolute;left:160px;right:160px;top:458px;border-bottom:2px solid #efedf2}

#s14 .task-shell{position:absolute;left:180px;top:291px;width:1560px;height:551px;border:3px solid #101112;border-radius:42px;background:#fff}
#s14 .shell-label{position:absolute;left:68px;top:69px;font-size:27px;letter-spacing:3px;color:#99939f}
#s14 .shell-title{position:absolute;left:68px;top:145px;font-size:77px;font-weight:750;letter-spacing:-2px;line-height:1.3}
#s14 .shell-note{position:absolute;left:68px;top:281px;font-size:35px;color:#88818f;line-height:1.65}
#s14 .shell-divider{position:absolute;left:527px;top:54px;bottom:54px;width:2px;background:#e7e1ed}
#s14 .task-layer{position:absolute;left:780px;top:410px;width:830px;height:282px;border:2px solid #dcd5e5;border-radius:23px;box-shadow:0 17px 30px -26px #10111255;background:#fff;transform-origin:left center;overflow:hidden}
#s14 .layer1{z-index:5;background:#101112;border-color:#101112}
#s14 .layer2{z-index:4;transform:translate(18px,18px);background:#efe9f6}
#s14 .layer3{z-index:3;transform:translate(36px,36px);background:#e2d6ee}
#s14 .layer-content{position:absolute;left:29px;right:29px;top:27px;display:flex;align-items:center;gap:30px;opacity:0;white-space:nowrap}
#s14 .layer-num{font-size:25px;color:#b8a7cc;width:40px;flex:none}
#s14 .layer-key{font-size:50px;font-weight:700;letter-spacing:-1px;width:250px;flex:none}
#s14 .layer-detail{font-size:32px;color:#8d8398;margin-left:auto}
#s14 .closed-cover{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:#cdb7f5;font-size:76px;font-weight:700;letter-spacing:-2px}
#s14 .layer-ruler{position:absolute;left:738px;top:357px;height:425px;width:18px;border-left:2px solid #cdb7f5;border-top:2px solid #cdb7f5;border-bottom:2px solid #cdb7f5;opacity:0}

#s09 .lead-label,#s09 .join{color:#747782}
#s11 .cause-arrow{color:#787382}
#s14 .shell-label{color:#77717e}
#s14 .layer1 .layer-num,#s14 .layer2 .layer-num{color:#77638f}

#s10 .qnum,#s10 .depth-mark{color:#746d7f}

js:
{
  // Each block uses absolute spoken chunk starts supplied by the parent.
  // Scene visibility and subtitles are exclusively controlled by the parent.
  // X09: the full sentence stays intact; only one noun carries the live accent.
  tl.fromTo('#s09 .sentence',{y:12,opacity:0},{y:0,opacity:1,duration:.28,ease:'power2.out',immediateRender:false},0);
  for(let j=0;j<3;j++){
    const current='#s09 .w'+(j+1), when=at('X09',j);
    if(j>0){
      tl.to('#s09 .w'+j,{y:0,scale:1,color:'#101112',duration:.24,ease:'power2.out'},when);
      tl.to('#s09 .w'+j+' .beat',{scaleX:0,duration:.2,ease:'power2.in'},when);
    }
    tl.to(current,{y:-17,scale:1.09,color:'#7451b8',duration:.3,ease:'power2.out'},when);
    tl.to(current+' .beat',{scaleX:1,duration:.28,ease:'power2.out'},when+.05);
  }

  // X10: preceding questions become a compact reading history.
  tl.fromTo('#s10 .q1',{x:40,opacity:0},{x:0,opacity:1,duration:.28,ease:'power2.out',immediateRender:false},6);
  tl.to('#s10 .q1',{y:-230,scale:.60,opacity:.46,duration:.4,ease:'power3.inOut'},at('X10',1));
  tl.to('#s10 .known',{opacity:1,duration:.22},at('X10',1)+.16);
  tl.fromTo('#s10 .q2',{x:190,y:65,opacity:0},{x:0,y:0,opacity:1,duration:.36,ease:'power3.out',immediateRender:false},at('X10',1)+.22);
  tl.to('#s10 .q2',{y:-118,scale:.66,opacity:.64,duration:.36,ease:'power3.inOut'},at('X10',2));
  tl.fromTo('#s10 .q3',{x:160,y:75,opacity:0},{x:0,y:0,opacity:1,duration:.36,ease:'power3.out',immediateRender:false},at('X10',2)+.22);
  tl.to('#s10 .q-underline',{scaleX:1,duration:.32,ease:'power2.out'},at('X10',2)+.34);
  tl.to('#s10 .depth-mark',{opacity:1,duration:.22},at('X10',2)+.25);

  // X11: a single focus moves along a meaningful causal connection.
  tl.to('#s11 .cause-signal',{opacity:1,duration:.2},at('X11',0));
  tl.to('#s11 .n1',{color:'#101112',duration:.24},at('X11',0));
  tl.to('#s11 .tick1',{attr:{stroke:'#b497df'},duration:.24},at('X11',0));
  tl.to('#s11 .note1',{opacity:1,duration:.25},at('X11',0)+.14);
  tl.to('#s11 .cause-signal',{attr:{cx:960},duration:.46,ease:'power2.inOut'},at('X11',1));
  tl.to('#s11 .cause-passed',{strokeDashoffset:590,duration:.46,ease:'power2.inOut'},at('X11',1));
  tl.to('#s11 .n2',{color:'#101112',duration:.28},at('X11',1)+.16);
  tl.to('#s11 .tick2',{attr:{stroke:'#b497df'},duration:.22},at('X11',1)+.22);
  tl.to('#s11 .note2',{opacity:1,duration:.24},at('X11',1)+.23);
  tl.to('#s11 .cause-signal',{attr:{cx:1550},duration:.46,ease:'power2.inOut'},at('X11',2));
  tl.to('#s11 .cause-passed',{strokeDashoffset:0,duration:.46,ease:'power2.inOut'},at('X11',2));
  tl.to('#s11 .n3',{color:'#101112',duration:.2},at('X11',2)+.14);
  tl.to('#s11 .n3 .outcome-bg',{scaleX:1,duration:.28,ease:'power2.out'},at('X11',2)+.18);
  tl.to('#s11 .n3 .large',{color:'#cdb7f5',duration:.24},at('X11',2)+.18);
  tl.to('#s11 .tick3',{attr:{stroke:'#7451b8'},duration:.2},at('X11',2)+.26);
  tl.to('#s11 .note3',{opacity:1,duration:.22},at('X11',2)+.24);

  // X12: challenge the false relation first, then replace the claim in place.
  tl.fromTo('#s12 .myth',{y:15,opacity:0},{y:0,opacity:1,duration:.26,ease:'power2.out',immediateRender:false},18);
  tl.to('#s12 .wrong-line',{width:171,duration:.28,ease:'power2.out'},at('X12',1));
  tl.to('#s12 .not-always',{opacity:1,y:0,duration:.26,ease:'power2.out'},at('X12',1)+.05);
  tl.to('#s12 .myth',{color:'#aaa5b0',duration:.2},at('X12',1)+.09);
  tl.to('#s12 .myth,#s12 .not-always,#s12 .belief-label',{opacity:0,duration:.2},at('X12',2));
  tl.fromTo('#s12 .new-rule',{y:16,opacity:0},{y:0,opacity:1,duration:.34,ease:'power2.out',immediateRender:false},at('X12',2)+.12);
  tl.to('#s12 .goal-mark',{scaleX:1,duration:.28,ease:'power2.out'},at('X12',2)+.17);
  tl.to('#s12 .clear-label,#s12 .action-note',{opacity:1,duration:.25},at('X12',2)+.23);

  // X13: these are the original phrase nodes, not duplicated replacement text.
  for(let j=0;j<3;j++){
    const n=j+1, when=at('X13',j);
    tl.to('#s13 .f'+n,{y:301,duration:.48,ease:'power3.inOut'},when);
    tl.to('#s13 .p'+n,{opacity:0,duration:.17},when+.03);
    tl.to('#s13 .slot'+n,{borderColor:'#b99bdc',duration:.26},when+.16);
    tl.to('#s13 .slot'+n+' .slot-fill',{scaleY:1,duration:.31,ease:'power2.out'},when+.13);
    tl.to('#s13 .slot'+n+' .slot-num',{color:'#7451b8',duration:.22},when+.18);
    tl.to('#s13 .slot'+n+' .slot-check',{opacity:1,duration:.18},when+.29);
    if(j>0)tl.to('#s13 .link'+j,{opacity:1,duration:.2},when+.25);
  }
  tl.to('#s13 .sentence-label,#s13 .sentence-guide',{opacity:0,duration:.23},at('X13',2)+.12);

  // X14: the outer task boundary stays fixed while its interior becomes legible.
  tl.fromTo('#s14 .task-shell',{opacity:0},{opacity:1,duration:.22,immediateRender:false},30);
  const open=at('X14',1), last=at('X14',2);
  tl.to('#s14 .closed-cover',{opacity:0,duration:.17},open);
  tl.to('#s14 .layer1',{x:0,y:-50,height:120,backgroundColor:'#cdb7f5',borderColor:'#cdb7f5',duration:.46,ease:'power3.inOut'},open);
  tl.to('#s14 .layer2',{x:20,y:100,height:120,backgroundColor:'#fff',duration:.46,ease:'power3.inOut'},open);
  tl.to('#s14 .layer3',{x:40,y:250,height:120,backgroundColor:'#f6f2fa',duration:.46,ease:'power3.inOut'},open);
  tl.to('#s14 .layer1 .layer-content,#s14 .layer2 .layer-content',{opacity:1,duration:.26},open+.19);
  tl.to('#s14 .layer-ruler',{opacity:1,duration:.28},open+.2);
  const material=Math.min(open+.63,last-.24);
  tl.to('#s14 .layer1',{backgroundColor:'#fff',borderColor:'#dcd5e5',duration:.22},material);
  tl.to('#s14 .layer2',{backgroundColor:'#cdb7f5',borderColor:'#cdb7f5',duration:.22},material);
  tl.to('#s14 .layer2',{backgroundColor:'#fff',borderColor:'#dcd5e5',duration:.23},last);
  tl.to('#s14 .layer3',{x:70,backgroundColor:'#101112',borderColor:'#101112',duration:.4,ease:'power2.out'},last);
  tl.to('#s14 .layer3 .layer-content',{opacity:1,duration:.26},last+.16);
  tl.to('#s14 .layer3 .layer-key',{color:'#cdb7f5',duration:.24},last+.13);
  tl.to('#s14 .layer3 .layer-detail',{color:'#ece5f4',duration:.24},last+.13);
}
